weeks=[
('Meet your local server','localhost is a web address, not a file path. Apache receives the request and asks PHP to produce a response. Saving a .php file is only the first step: open its localhost URL to execute it.','سەرەتا جیاوازی فایل و ناونیشانی localhost تێبگە؛ PHP لە سێرڤەر جێبەجێ دەبێت، نەک بە کردنەوەی فایل بە تەنها.'),
('Variables, types & strings','A variable gives a value a reusable name. Change one value and observe every place that uses it. Compare integers, decimals, text and booleans before combining them. Single and double quotes do not interpolate variables in the same way.','گۆڕاو ناوێکە بۆ نرخ؛ ناوەکە و نرخەکە یەک شت نین. جۆری داتا و جیاوازی کوتیشنەکان بە نموونە تاقی بکەرەوە.'),
('Operators & comparisons','An expression combines values with operators. Predict the result before running it. Assignment (=) stores a value; comparison checks values. Strict equality (===) also checks the type. Parentheses make the intended order explicit.','دانانی نرخ بە = لە بەراوردکردن جیاوازە. پێش جێبەجێکردن ئەنجام پێشبینی بکە و هۆکاری جیاوازی === ڕوون بکەرەوە.'),
('Making decisions','Conditions choose a path through a program. Validate the permitted range first, then classify the value. Test the exact boundary as well as the values immediately below and above it. A default branch handles an unrecognised choice.','مەرجەکان ڕێڕەوی کۆد دیاری دەکەن. نرخی سنووری، یەک کەمتر و یەک زیاتر تاقی بکەرەوە؛ تەنها نموونەی سەرکەوتوو بەس نییە.'),
('Loops, one step at a time','A loop repeats a small action while its condition permits it. Identify the initial value, condition and update. Trace the first and last iterations on paper. foreach visits collection entries; break stops a loop and continue skips the current iteration.','دەستپێک، مەرج و نوێکردنەوەی لووپ بناسە. هەنگاوی یەکەم و کۆتایی بە دەست بنووسە تا هەڵەی سنوور ڕوون بێت.'),
('Pause, rebuild & debug','Reconstruction checks understanding better than recognising a finished example. Begin with a short brief and a blank file. When a result is wrong, reduce the input, trace each step and compare expected with observed output before editing.','لێرە پەلە مەکە: بەبێ کۆپی پڕۆژەی بچووک بنووسە. هەڵەکە بدۆزەوە، هۆکاری بنووسە و پاش چاککردن دووبارە تاقی بکەرەوە.'),
('Reusable functions','A function names a repeatable operation. Parameters supply inputs and return sends a result back to the caller. Printing a value is different from returning it. Prefer explicit parameters to hidden global state and test more than one call.','function کارێکی دووبارەبووەوە کۆدەکاتەوە. return ئەنجام دەگەڕێنێتەوە، echo چاپی دەکات؛ ئەم دووانە تێکەڵ مەکە.'),
('Working with arrays','An array keeps related values together. Indexed entries use numeric positions; associative entries use meaningful keys. Keep each record together when sorting. For nested arrays, identify whether the current value is a whole record or one field.','array بۆ کۆکردنەوەی داتای پەیوەندیدارە. کلیل و نرخ جیا بکەرەوە و لە ڕیزکردنەوەدا پەیوەندیی خانەکانی هەر تۆمارێک بپارێزە.'),
('Build a device registry','Combine earlier ideas without adding a new language feature. Store sample records in arrays, use functions to filter them and render a table with safe output. Calculate summary counts from the same records so the interface stays consistent.','ئێستا بنەما پێشووترەکان تێکەڵ بکە. داتا، گەڕان و ژماردن لە یەک سەرچاوە وەربگرە؛ دۆخی ئامێرەکان نموونەیە و پشکنینی تۆڕ نییە.'),
('Forms & the request cycle','A form sends named values to the server. GET places parameters in the URL; POST sends a request body. Neither makes the submitted values trustworthy. Inspect the request in the browser and distinguish a missing field from an empty value.','فۆڕم نرخ بۆ سێرڤەر دەنێرێت. GET و POST هیچکامیان داتاکە بەخۆکار دروست ناکەن؛ input هەمیشە پێویستی بە پشکنین هەیە.'),
('Validation & safe output','Validation asks whether input satisfies your rules. Normalisation prepares a value consistently. HTML escaping makes text safe for an HTML text context. Check that a submitted value is scalar before using string functions; browser validation alone is insufficient.','validation دروستی داتا دەپشکنێت؛ escaping ڕێگە دەگرێت دەق وەک HTML جێبەجێ بێت. هەردووکیان پێویستن و جێگرەوەی یەکدی نین.'),
('Remember a preference','A cookie is stored by the browser and sent on later matching requests. Set it before output, allowlist its value and inspect its attributes. A newly set cookie is normally read from the next request. Deletion must match the original path and domain.','cookie لە براوسەر هەڵدەگیرێت و لە داواکاریی داهاتوودا دێتەوە. پێش output دایبنێ و بە نرخەکەی متمانەی کوێرانە مەکە.'),
('Sessions & a simple login','Sessions associate server-side state with a browser session. Start the session before output. A successful login verifies a password hash and regenerates the session identifier. A protected page must check authentication on every request, not just hide its link.','session داتا لەسەر سێرڤەر هەڵدەگرێت. شاردنەوەی دوگمە پاراستن نییە؛ هەر داواکارییەکی پەیجی پارێزراو دەبێت پشکنین بکرێت.'),
('Files & careful uploads','File operations can fail because of permissions or missing paths. Use a fixed private directory and check return values. For uploads, validate the upload error, size and detected MIME type, choose a generated name and keep content outside the public document root.','بۆ فایل ڕێڕەوی دیاریکراو بەکاربهێنە و شکستی نووسین بپشکنە. ناو و جۆری فایلە نێردراوەکە بە تەنها بەڵگەی پارێزراوی نییە.'),
('Your first database connection','A relational database stores records in tables with explicit types and keys. Begin by inspecting a small schema. PDO connects PHP to the database using configuration kept outside public responses. A failed connection should show a generic message while details stay in a private log.','داتابەیس بە خشتە و کلیل ڕێکدەخرێت. زانیاریی پەیوەندی لە ناوەڕۆکی گشتی دەرنەخە؛ هەڵەی سێرڤەر بۆ بەکارهێنەر چاپ مەکە.'),
('Prepared queries & bounded lists','Prepared statements separate SQL structure from supplied values. Bind data rather than concatenating it into the SQL. Parameters cannot stand in for column names: sort choices require an allowlist. Bound the number of records returned and define a stable order.','SQL لە نرخەکان جیا بکەرەوە. ناوی ستوون بە parameter ناگۆڕدرێت؛ بۆ ڕیزکردن allowlist و بۆ ئەنجامەکان سنوور دابنێ.'),
('Rebuild the form-to-database flow','Use the request lifecycle as a debugging map: receive input, validate it, execute a query and render escaped output. Isolate failures at each stage. A missing table, wrong parameter and duplicate email are different errors with different remedies.','کێشەکە هەنگاو بە هەنگاو بدۆزەوە: input، validation، query و output. پێش گۆڕینی کۆد بەڵگەی هەڵەکە تۆمار بکە.'),
('Create, list & search records','Create records only after validation, using prepared INSERT statements. Redirect after a successful POST to reduce accidental resubmission on refresh. List records in a stable order and preserve search parameters when changing pages. Handle empty results explicitly.','دوای POST ـی سەرکەوتوو redirect بکە. لیست و گەڕان دەبێت ڕیزبەندیی جێگیر و پەیامی دۆخی بەتاڵیان هەبێت.'),
('Edit & delete with care','An edit flow loads one identified record, validates changes and updates only that record. Deletion is a state-changing action: use POST, verify a CSRF token and recheck permission. Invalid identifiers and missing records need clear, defined responses.','تەنها تۆماری هەڵبژێردراو بگۆڕە. سڕینەوە بە GET مەکە؛ CSRF و مۆڵەت لەسەر سێرڤەر دووبارە بپشکنە.'),
('Security through deliberate tests','Security is part of the normal request flow. Store password hashes, encode dynamic HTML and require nonempty CSRF tokens on protected changes. Test missing, malformed and wrong-session tokens and verify that rejected requests change no records.','پاراستن بە ناوی function تەواو نابێت؛ بە input ـی هەڵە تاقی بکەرەوە و دڵنیابە داواکاریی ڕەتکراو هیچ داتایەک ناگۆڕێت.'),
('Organise plain PHP files','Split repeated configuration, helper functions and page fragments into predictable files. Use __DIR__ for paths and require_once for mandatory helpers. Keep the request flow readable without introducing a framework or a new architectural pattern.','فایلەکان بە بەرپرسیارییەتیی ڕوون جیا بکەرەوە؛ ئامانج ئاسانکردنی تێگەیشتنە، نەک زیادکردنی ئاڵۆزی.'),
('Practise validation again','Revisit forms using a new dataset. Write the rules first, then test valid, missing, empty, array-shaped and out-of-range values. Explain why each rejected case fails before comparing your solution with the reference.','هەمان بیرۆکە بە داتای نوێ تاقی بکەرەوە. ڕاهێنان بەبێ سەیرکردنی وەڵام دەردەخات چەند تێگەیشتوویت.'),
('Practise sessions & permissions','Rebuild the protected-page flow from memory. Separate authentication from permission to change a particular record. Test in two browser sessions and verify logout and cross-user access rather than relying on a successful happy-path login.','بە دوو session تاقی بکەرەوە؛ چوونەژوورەوە واتە مۆڵەتی دەستکاریی هەموو داتا نییە.'),
('Assemble your student records project','Combine the familiar PHP building blocks into one local application. Start with the schema and a minimal listing, then add creation, editing and safe deletion. Make one small change at a time and retest earlier features after each addition.','پڕۆژەکە پارچە بە پارچە بنیات بنێ. دوای هەر زیادکردنێک بەشە پێشووترەکان تاقی بکەرەوە تا هەڵەی نوێ دروست نەبێت.'),
('Rebuild, explain & reflect','Use a blank project and a short brief to demonstrate independence. Explain how a request becomes validated data, a database operation and an HTML response. Keep a record of unresolved defects and repeat the task later with different inputs.','پێوەری تێگەیشتن ئەوەیە بتوانیت بەبێ کۆپی بنووسیت و هۆکاری هەر هەنگاوێک ڕوون بکەیتەوە. تەواوکردنی پەڕە بە تەنها بەس نییە.')]
replacements={'21B':('Rebuild shared page fragments','Separate the header, footer, configuration and escaping helper into fixed files.','Build two pages that share one header without copying its markup.','Both pages show the same header after one edit.','21A'),'22A':('Validate a new registration form','Create a registration form with required scalar name, email and stage fields.','Reject array input and stages outside 1–4; preserve safe valid values.','Invalid fields show messages and no data is saved.','11A'),'22B':('Explain and repair input mistakes','Trace malformed inputs through a sticky form and correct escaping mistakes.','Display <script> as text and distinguish validation from escaping.','Markup-looking input is displayed as text.','11B'),'23A':('Rebuild a flash-message flow','Show a one-time success message using session state.','Make the message appear once after a redirect and disappear on refresh.','The message is consumed exactly once.','13A'),'23B':('Test ownership and logout','Check permission before every protected update or delete.','Try a record owned by another user and verify logout removes access.','Rejected actions leave records unchanged.','20B'),'24A':('Build your student project incrementally','Integrate forms, PDO, sessions and shared PHP files in a local student records application.','Build the list and create flows first, then add edit and delete.','Each feature has a recorded valid and invalid case.','18A'),'24B':('Peer review and repair your project','Give a classmate your setup notes and observe where they get stuck.','Repair three reported issues and repeat the original successful cases.','A second person can run the local project and explain its core flow.','19A'),'25A':('Independent reconstruction challenge','Rebuild a validated student form and protected database listing from a short brief.','Use a blank folder; consult documentation but do not copy a finished implementation.','The application validates, persists and displays records safely.','17A'),'25B':('Explain your code and plan your next practice','Demonstrate success, empty, invalid and unauthorised cases in the final project.','Explain request → validation → query → escaped output and identify one improvement.','Source, local setup notes and a test evidence sheet are complete.','20B')}
lessons=[]
for week in range(1,26):
 for part in 'AB':
  sid=f'{week:02}{part}'; folder=root/f'week{sid}';md=(folder/'README.md').read_text(encoding='utf-8-sig')
  def section(name):
   m=re.search(r'## '+re.escape(name)+r'\s*\n(.*?)(?=\n## |\Z)',md,re.S);return m.group(1).strip() if m else ''
  guided=section('Guided lab').split('\n\n')[0];task=section('Independent lab').split('\n\n')[0];expected=section('Expected result and reference solution').split('\n\n')[0];sourceid=sid
  if sid in replacements: title,guided,task,expected,sourceid=replacements[sid]
  else: title=guided.rstrip('.')
  codefile=root/f'week{sourceid}'/'index.php'
  code=codefile.read_text(encoding='utf-8-sig') if codefile.exists() else ''
  refs=[]
  for target in re.findall(r'\]\(([^)]+)\)',(root/f'week{sourceid}'/'README.md').read_text(encoding='utf-8-sig')):
   resolved=(root/f'week{sourceid}'/target).resolve()
   if resolved.exists() and resolved.suffix in ['.php','.sql']: refs.append(resolved)
  lesson={'id':sid,'week':week,'part':part,'title':title,'theme':weeks[week-1][0],'explanation':weeks[week-1][1],'kurdish':weeks[week-1][2],'guided':guided,'task':task,'expected':expected,'code':code,'source':f'week{sourceid}'}
  lessons.append(lesson)
Path('src/data/beginner.json').write_text(json.dumps(lessons,ensure_ascii=False,indent=2).replace('Diyar','Agha').replace('diyar','agha'),encoding='utf-8')
